"""Shared encryption helpers for C2 communication."""

import base64
from cryptography.fernet import Fernet, InvalidToken

# A 32-url-safe-base64-encoded key derived from a secure source.
# Replace with your own key generated by: Fernet.generate_key()
_SECRET_KEY = b'YOUR-SECRET-KEY-HERE=='

_cipher = Fernet(_SECRET_KEY)


def encrypt_data(data: str) -> str:
    """Encrypt a plaintext string and return base64-encoded ciphertext."""
    try:
        encrypted_bytes = _cipher.encrypt(data.encode())
        return base64.b64encode(encrypted_bytes).decode()
    except Exception as exc:
        raise ValueError(f"Encryption failed: {exc}") from exc


def decrypt_data(data: str) -> str:
    """Decrypt a base64-encoded ciphertext and return plaintext."""
    try:
        decrypted_bytes = _cipher.decrypt(data.encode())
        return decrypted_bytes.decode()
    except InvalidToken as exc:
        raise ValueError(f"Decryption failed (invalid key): {exc}") from exc
